import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except (TypeError, ValueError):
        return v is None


def _neq(a, b):
    """NULL-aware inequality: NULL vs NULL -> not changed; NULL vs value -> changed."""
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null or b_null:
        return True
    return a != b


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    """Fetch an input DataFrame by name, tolerant of case/naming variations."""
    if name in inputs:
        return inputs[name]
    lname = name.lower()
    for k in inputs:
        if k.lower() == lname:
            return inputs[k]
    # try common suffix variants like '_out' stripped, or exact substring match
    for k in inputs:
        if lname in k.lower() or k.lower() in lname:
            return inputs[k]
    raise KeyError(f"Could not find input matching '{name}' in {list(inputs.keys())}")


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, 'DIM_ACCT').copy()
    stg = _get_input(inputs, 'STG_ACCT').copy()

    # Normalize is_current to int
    if 'is_current' in dim.columns:
        dim['is_current'] = dim['is_current'].astype(int)

    # ---- Step 1: Dedup STG_ACCT to latest per acct_id by update_date,
    # ties broken by greater (email, tier) lexicographic pair ----
    if len(stg) > 0:
        stg_sorted = stg.sort_values(
            by=['update_date', 'email', 'tier'],
            na_position='first',
            kind='mergesort'
        )
        stg_dedup = stg_sorted.groupby('acct_id', as_index=False, sort=False).tail(1)
    else:
        stg_dedup = stg.copy()

    # ---- Prepare mutable working set of DIM_ACCT rows ----
    dim = dim.reset_index(drop=True)
    rows = dim.to_dict('records')

    def get_current_idx(acct_id):
        for i, r in enumerate(rows):
            if r['acct_id'] == acct_id and int(r.get('is_current', 0)) == 1:
                return i
        return None

    for _, s in stg_dedup.iterrows():
        acct_id = s['acct_id']
        s_email = s['email']
        s_tier = s['tier']
        s_update_date = s['update_date']

        idx = get_current_idx(acct_id)

        if idx is None:
            # No current row -> insert new current version
            rows.append({
                'acct_id': acct_id,
                'email': s_email,
                'tier': s_tier,
                'eff_start_date': s_update_date,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })
        else:
            c = rows[idx]
            tier_changed = _neq(c.get('tier'), s_tier)
            email_changed = _neq(c.get('email'), s_email)

            if tier_changed:
                # Expire current row (Type-2 versioning)
                rows[idx]['eff_end_date'] = s_update_date
                rows[idx]['is_current'] = 0

                rows.append({
                    'acct_id': acct_id,
                    'email': s_email,
                    'tier': s_tier,
                    'eff_start_date': s_update_date,
                    'eff_end_date': pd.NaT,
                    'is_current': 1,
                })

            if email_changed:
                # Type-1 retro-overwrite: update ALL rows (history and current)
                # for this acct_id with the new email value.
                for r in rows:
                    if r['acct_id'] == acct_id:
                        r['email'] = s_email

    out = pd.DataFrame(rows, columns=[
        'acct_id', 'email', 'tier', 'eff_start_date', 'eff_end_date', 'is_current'
    ])

    return {'dim_acct_out': out}
